&&          &+ \dfrac{\Big[n^2 + \Big(\dfrac{1}{2}\Big)^2\Big]\Big[n^2 + \Big(\dfrac{5}{2}\Big)^2\Big]\Big[n^2 + \Big(\dfrac{9}{2}\Big)^2\Big]}{ 6!} x^6 + \cdots
\end{align*}$$ and\
$$\begin{align*}
&&l_n(x) = -q_{-\frac{1}{2}+ni} (x) &= x + \dfrac{n^2 + \Big(\dfrac{3}{2}\Big)^2}{ 3!} x^3 + \dfrac{\Big[n^2 + \Big(\dfrac{3}{2}\Big)^2\Big]\Big[n^2 + \Big(\dfrac{7}{2}\Big)^2\Big]}{ 5!} x^5&&\\[1ex]
&&          &+ \dfrac{\Big[n^2 + \Big(\dfrac{3}{2}\Big)^2\Big]\Big[n^2 + \Big(\dfrac{7}{2}\Big)^2\Big]\Big[n^2 + \Big(\dfrac{11}{2}\Big)^2\Big]}{ 7!} x^7 + \cdots&&
\end{align*}$$ $k_n (x)$ and $l_n (x)$ are convergent if $x^2 < 1$, but are divergent if $x^2 = 1$.\
7.Show by the aid of Example 5 that $$\arraycolsep=0.3em
\begin{array}{c|c}
V= \dfrac{1}{\sqrt{r}} \sin (n \log r)K_n(\cos \theta),  & V= \dfrac{1}{\sqrt{r}} \sin (n \log r)K_n(-\cos \theta),\\[1em]
V= \dfrac{1}{\sqrt{r}} \cos (n \log r)K_n(\cos \theta),  & V= \dfrac{1}{\sqrt{r}} \cos (n \log r)K_n(-\cos \theta),
\end{array}$$ $$\begin{align*}
&\text{are solutions of}&   &rD_r^2(rV) + \dfrac{1}{\sin \theta} D_\theta (\sin \theta D_\theta V) = 0&\phantom{are solutions of}\\[-5ex]
\end{align*}$$ $$\begin{align*}
&\text{if }&  K_n(x) =& {}_1P_{-\frac{1}{2}+ni}(x)=1-\dfrac{n^2+\Big(\dfrac{1}{2}\Big)^2}{2}(x-1)&\\[0.5em]
