The question of the flow of heat in three dimensions involves a problem
not unlike the last.

Suppose the initial temperatures of all points in a sphere of radius $c$ given,
and let the surface be kept at the temperature zero. Then we have to solve
the equation
\[
D_t u=\frac{a^2}{r^2}\biggr [D_r(r^2 D_r u) + \frac{1}{\sin\theta} D_{\theta}(\sin\theta D_{\theta} u) + \frac{1}{\sin^2\theta} D_{\phi}^2 u\biggr]    \tag{1}
\]
(\smallrom{IV} Art.~1) subject to the conditions
\begin{gather*}
   u = 0 \quad \text{when}\quad  r = c,\\
   u =f(r, \theta, \phi)\quad \text{when}\quad  t = 0.
\end{gather*}
If we assume $u = T.R.V$  where $T$ is a function of $t$ only, $R$ of $ r$ only, and $V$
of $\theta$ and $\phi$ only, (1) can be broken up into
\begin{gather*}
\frac{dT}{dt} + a^2 \alpha^2 T = 0    \tag{2}\\
 m(m+1)V + \frac{1}{\sin\theta }D_{\theta} (\sin\theta D_{\theta} V) + \frac{1}{\sin^2 \theta} D_{\phi}^2 V = 0    \tag{3}
\end{gather*}
\begin{flalign*}
&\text{and}&\frac{ d^2R}{dr^2} + \frac{2}{r }\frac{dR}{dr }\ + \biggr[\alpha^2 - \frac{m(m+1)}{r^2} \biggr ]R=0.  && \tag{4}
\end{flalign*}
Hence $T = e^{-a^2 \alpha^2 t}$, $V=Y_m (\mu, \phi)$ [v.\ Art.~102 (2)], and $R$ is still to be found.
If in (4) we let $x=\alpha r$ and $z=R\sqrt{\alpha r}$ it becomes
\[
\frac{d^2z}{dx^2} + \frac{1}{x} \frac{dz}{dx} + \biggr [ 1 - \frac{(m+\frac{1}{2})^2 }{x^2} \biggr ] z=0
\]
which is satisfied by $z=J_{m+\frac{1}{2}} (x)$. (v.\ Art.~17.)
\begin{flalign*}
&\text{\indent Therefore}&  R= \frac{1}{\sqrt{\alpha r }}J_{m+\frac{1}{2}} (\alpha r).&&\phantom{\indent Therefore}
\end{flalign*}
\begin{flalign*}
&&f(r,\theta,\phi)&=\dfrac{1}{4\pi}\sum\limits^{m=\infty}_{m=0} (2m+1) \int\limits^{2\pi}_0 d\phi_1  \int\limits^{\pi}_0 f(r,\theta_1,\phi_1)P_m(\cos \gamma)\sin\theta_1 d\theta_1&\tag*{by (3) Art.~114,}\\
&&&=\sum\limits^{m=\infty}_{m=0} \sum\limits^{n=m}_{n=0} [A_{m,n}f_{m,n}(r)\cos n\phi + B_{m,n}F_{m,n}(r)\sin n\phi]P_m^n(\mu).&
\end{flalign*}
\[
\sqrt{r}f_{m,n}(r)=\sum\limits^{k=\infty}_{k=0}  C_{m,n,k}J_{m+\frac{1}{2}}(\alpha_kr)
\]
where $\alpha_k$ is a root of the equation
\[
\dfrac{J_{m+\frac{1}{2}}(\alpha c)}{(\alpha c)^{m+\frac{1}{2}}}=0
\]
\begin{flalign*}
&\text{and}   &&C_{m,n,k}= \dfrac{2\displaystyle \int\limits^c_0 r^{\frac{3}{2}}f_{m,n}(r)J_{m+\frac{1}{2}}(\alpha_kr)dr}{c^2[J'_{m+\frac{1}{2}}(\alpha_kc)]^2}.&&\\
&                       &&\sqrt{r}F_{m,n}(r)=\sum\limits^{m=\infty}_{m=0}  D_{m,n,k}J_{m+\frac{1}{2}}(\alpha_kr)\\
&\text{where }&&      D_{m,n,k}= \dfrac{2\displaystyle\int\limits^c_0 r^{\frac{3}{2}}F_{m,n}(r)J_{m+\frac{1}{2}}(\alpha_kr)dr}{c^2[J'_{m+\frac{1}{2}}(\alpha_kc)]^2}.&&\phantom{where}
\end{flalign*}

The final solution is
\begin{multline*}
u=\dfrac{1}{\sqrt{r}}\sum\limits^{m=\infty}_{m=0} \sum\limits^{n=m}_{n=0} \bigg[P_m^n(\mu)\sum\limits^{k=\infty}_{k=1} (A_{m,n}C_{m,n,k}\cos n\phi\\
                         \vphantom{ \sum\limits^{n=m}_{n=0}}
                         +B_{m,n}D_{m,n,k} \sin n\phi)e^{-a^2\alpha_k^2 t} J_{m+\frac{1}{2}}(\alpha_kr)\bigg]
\end{multline*}
cf.\ Riemann, Par.\ Dif.\ Gl., \S\S~72 and 73.
